name = #{name}, type = #{type}, threshold = #{threshold}, discount = #{discount}, total_count = #{totalCount}, per_user_limit = #{perUserLimit}, valid_type = #{validType}, valid_days = #{validDays}, start_time = #{startTime}, end_time = #{endTime}, scope_type = #{scopeType}, apply_category_id = #{applyCategoryId}, apply_product_ids = #{applyProductIds}, status = #{status}, update_time = #{updateTime}
